import {createCMS} from './cms.js';
let state, eventTab='upcoming';
const discussionDrafts=new Map();
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('main').focus();document.querySelector('main').scrollIntoView()});
const main=document.querySelector('main'), dialog=document.querySelector('dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const external=(url,label,cls='')=>url?`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:'';
const icons={like:'M7 10v11H3V10h4Zm0 0 5-8c2 0 2 3 1 6h6a2 2 0 0 1 2 2l-2 9a2 2 0 0 1-2 2H7',dislike:'M7 14V3H3v11h4Zm0 0 5 8c2 0 2-3 1-6h6a2 2 0 0 0 2-2l-2-9a2 2 0 0 0-2-2H7',comment:'M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0Z',repost:'M4 8h14l-4-4M20 16H6l4 4M18 8l-4 4M6 16l4-4',report:'M5 22V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]}" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'To be confirmed';
const admin=()=>state.user?.role==='admin';
const toast=s=>{const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3500)};
async function api(action,data={}){const r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const body=await r.json();if(!r.ok)throw Error(body.error||'Something went wrong. Please try again.');return body}
async function load(){const r=await fetch('/api/state');if(!r.ok)throw Error('Unable to load the website. Please refresh.');state=await r.json()}
function shell(){document.querySelector('#header').innerHTML=`<div class="wrap nav"><a class="brand" href="#/"><img src="/assets/logo.png" alt="Law Society ATC Penang logo"><div><strong>Law Society</strong><span>ATC PENANG · 2026/27</span></div></a><nav class="links" aria-label="Main navigation"><a class="nav-section" href="#/about">About us</a><a class="nav-section" href="#/events">Events</a><a class="nav-section" href="#/contact">Contact</a><button class="text-button mobile-menu" data-action="menu" aria-label="Open navigation">Menu</button>${state.user?`<button class="text-button" data-action="account">${esc(state.user.name)}</button>`:'<button class="btn outline" data-action="login">Sign in</button>'}</nav></div>`;document.querySelector('#footer').innerHTML=`<div class="wrap footer-inner"><span>© 2026 Law Society ATC Penang</span><span>2026 / 2027 Committee</span><a href="#/admin">Admin</a></div>`}
function home(){const s=state.settings,t=state.topics.find(t=>t.status!=='archived'),e=state.events.find(e=>e.status!=='past');main.innerHTML=`<div class="hero wrap"><div class="hero-top"><div><div class="eyebrow">A student-led society · ATC Penang</div><h1>The law.<br>Our <em>conversation.</em></h1><p class="hero-copy">A place to question, exchange perspectives and put legal knowledge into practice.</p></div><div class="hero-art"><img src="/assets/logo.png" alt="Law Society's gold Lady Justice emblem"><span class="vertical">LAW SOCIETY · ATC PENANG</span><span class="edition">THE 2026 / 27 CHAPTER</span></div></div><div class="hero-bottom"><div class="hero-feature"><div><div class="eyebrow">01 / Legal knowledge · Every two weeks</div><h3>${esc(t?.title||'Legal knowledge & discussion')}</h3><p>${t?`Explainer ${date(t.publish)} · Discussion ${date(t.discussion)}`:'Explore our legal conversations.'}</p></div><a class="btn" href="#/dialogue">Explore topic</a></div><div class="hero-feature"><div><div class="eyebrow">02 / Coming up at the society</div><h3>${esc(e?.title||'Our next activity')}</h3><p>${esc(e?.date||'Details to be announced')} · ${e?.status==='planned'?'Planned':'Upcoming'}</p></div><a class="btn outline" href="${e&&e.status!=='planned'?'#/event/'+e.id:'#/events'}">View events</a></div></div></div>
<section id="about" class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><span class="section-no">01</span> About the society</div><h2>Beyond the<br>lecture hall.</h2></div><div class="intro"><p>${esc(s.about)}</p></div></div><div class="about-body"><div class="principle"><span>LEARN</span><h3>Explore the questions.</h3><p>Look closer at contemporary legal issues through student research and open discussion.</p></div><div class="principle"><span>PRACTISE</span><h3>Find your argument.</h3><p>Develop research, analysis and advocacy through mooting and law-related activities.</p></div><div class="principle"><span>CONNECT</span><h3>Meet the profession.</h3><p>Learn from practising lawyers, alumni and peers, on campus and beyond.</p></div></div><div class="committee-head"><h3>The people behind it.</h3><span class="eyebrow">Committee · 2026/27</span></div><div class="committee">${s.committee.map(p=>`<div class="person"><span>${esc(p[0])}</span><strong>${esc(p[1])}</strong></div>`).join('')}</div></div></section>
<section id="events" class="section events-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><span class="section-no">02</span> Society events</div><h2>Out of the books.<br>Into the experience.</h2></div><div class="intro"><p>Competitions, conversations and a closer look at the legal profession.</p><small>Proposed programme · Dates subject to confirmation.</small></div></div><div class="tabs" role="tablist" aria-label="Event categories"><button role="tab" aria-selected="${eventTab==='upcoming'}" class="tab ${eventTab==='upcoming'?'active':''}" data-action="events-tab" data-value="upcoming">Upcoming & ongoing</button><button role="tab" aria-selected="${eventTab==='past'}" class="tab ${eventTab==='past'?'active':''}" data-action="events-tab" data-value="past">Past events</button></div><div id="event-list">${eventList()}</div></div></section>
<section id="contact" class="contact"><div class="wrap contact-grid"><div><div class="eyebrow"><span class="section-no">03</span> Get in touch</div><h2>A question?<br>Let’s talk.</h2></div><div class="contact-links"><a href="mailto:${esc(s.email)}"><small>EMAIL · PREFERRED</small>${esc(s.email)}</a>${external(s.instagram,'<small>INSTAGRAM</small>@lawsocietyatcpg_')}</div></div></section>`;cms.decorateHome()}
function eventList(){const items=state.events.filter(e=>eventTab==='past'?e.status==='past':e.status!=='past');return items.length?items.map(e=>{const body=`<div class="date-block">${esc(e.date)}</div><div><h3>${esc(e.title)}</h3><p>${esc(e.category)}</p></div><div class="status">${e.status==='planned'?'Details to follow':e.status==='past'?'View recap':e.status==='ongoing'?'Ongoing':'View details'}</div>`;return e.status==='planned'?`<div class="event-row planned">${body}</div>`:`<a class="event-row" href="#/event/${e.id}">${body}</a>`}).join(''):'<div class="empty"><h3>No past events yet.</h3><p>Recaps and photos will appear after each event.</p></div>'}
function topics(){main.innerHTML=`<div class="wrap page"><div class="breadcrumbs"><a href="#/">Home</a> / Legal knowledge</div><div class="eyebrow">Read. Consider. Join the conversation.</div><h1 class="page-title">Legal knowledge<br>& discussion.</h1><p class="topic-intro">One issue, different perspectives. Explore our fortnightly legal explainers and take part in the discussion.</p>${state.topics.map(t=>`<a class="topic-card" href="#/topic/${t.id}"><span class="badge">${esc(t.status==='open'?'Open for discussion':t.status==='archived'?'Discussion archive':'Coming up')}</span><h2>${esc(t.title)}</h2><p class="muted">${esc(t.summary)}</p><small>Explainer ${date(t.publish)} &nbsp; / &nbsp; Online discussion ${date(t.discussion)}</small></a>`).join('')||'<div class="empty">New legal topics will appear here.</div>'}</div>`}
function render(){cms.disposeLogo();shell();cms.decorateShell();const parts=(location.hash||'#/').slice(2).split('/'),route=parts[0];if(['','about','events','contact'].includes(route)){home();if(route)requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView());}else if(route==='dialogue'){topics();document.querySelector('.page-title').textContent=state.settings.dialogue_title;document.querySelector('.topic-intro').textContent=state.settings.dialogue_intro}else if(route==='topic')topicPage(parts[1]);else if(route==='event'){eventPage(parts[1]);cms.decorateEvent(parts[1])}else if(route==='event-preview'&&state.settings.moot_preview)cms.eventPreview();else if(route==='admin')cms.renderAdmin();else main.innerHTML='<div class="wrap page"><h2>Page not found.</h2><a href="#/">Return home</a></div>';restoreDiscussionDrafts();if(!['about','events','contact'].includes(route))window.scrollTo(0,0)}
function showDialog(html){dialog.innerHTML=`<div class="dialog-top"><span class="eyebrow">${esc(state.settings.site_name)} · ${esc(state.settings.location)}</span><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${html}<p class="error" id="form-error" role="alert"></p>`;cms.decorateDialog();if(!dialog.open)dialog.showModal()}
function login(){showDialog(`<h2>Join the conversation.</h2><p class="muted">Local student preview: try posting with a demo identity. Google sign-in will be connected before public launch.</p><form data-form="login"><input type="hidden" name="role" value="student"><label for="nickname">Display name</label><input id="nickname" name="name" required maxlength="40" autocomplete="nickname" placeholder="Your nickname"><div class="dialog-foot"><button class="btn" type="submit">Enter student demo</button></div></form>`)}
function requireUser(){if(state.user)return true;login();return false}
function topicPage(id){const t=state.topics.find(t=>t.id===id);if(!t){main.innerHTML='<div class="wrap page"><h2>Topic not found.</h2><a href="#/dialogue">Browse topics</a></div>';return}const posts=state.posts.filter(p=>p.topic===id).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.created-a.created);main.innerHTML=`<div class="wrap page"><div class="breadcrumbs"><a href="#/">Home</a> / <a href="#/dialogue">Legal knowledge</a> / Topic</div><span class="badge">${t.status==='open'?'Open for discussion':t.status==='archived'?'Archived · Read only':'Coming up'}</span><h1 class="page-title">${esc(t.title)}</h1><p class="topic-intro">${esc(t.summary)}</p><div class="discussion-layout"><div><article class="official"><span class="eyebrow">From the society</span><h3>The legal explainer</h3><p>${esc(t.content||'Our Research and PRM teams are preparing this topic. The official explainer will appear here when it is published.')}</p>${external(t.instagram,'Read the Instagram post','btn outline')}</article><h3 class="display" style="font-size:34px;margin-top:35px">The conversation</h3>${t.status==='open'?`<form class="composer" data-form="post"><input type="hidden" name="topic" value="${id}"><label for="post-body">${state.user?'Share your perspective':'Have a perspective to share?'}</label><textarea id="post-body" name="body" maxlength="4000" required placeholder="An argument, a question, a different way of looking at it…"></textarea><div class="composer-foot"><small class="muted">Discuss ideas respectfully.<br>Support factual claims with sources.</small><button class="btn" type="submit">${state.user?'Publish post':'Sign in to post'}</button></div></form>`:`<p class="small muted" style="margin-top:20px">${t.status==='archived'?'This discussion is preserved for reference.':'Posting opens when the society publishes the topic.'}</p>`}<div id="posts">${posts.map(postHTML).join('')||'<div class="empty"><h3>No posts yet.</h3><p>No student posts yet.</p></div>'}</div></div><aside><div class="side-card"><div class="eyebrow">Meet & discuss</div><h3 style="margin-top:10px">${date(t.discussion)}</h3><p>${esc(t.time)}</p>${t.meet?external(t.meet,'Join Google Meet','btn'):'<p class="small">The meeting link will be added here.</p>'}</div><div class="side-card secondary"><h3>A note on discussion</h3><p>Bring your reasoning, make room for other views and keep personal information private.</p><p>Student perspectives are contributions to a discussion, not legal advice.</p></div></aside></div></div>`}
function postHTML(p){const orig=p.original?state.posts.find(x=>x.id===p.original):null,comments=state.comments.filter(c=>c.post===p.id),reactions=state.reactions.filter(r=>r.post===p.id),my=reactions.find(r=>r.user===state.user?.id);return `<article class="post" id="post-${p.id}">${p.pinned?'<div class="pin">Pinned by the society</div>':''}${orig?`<div class="repost-note">${esc(p.author)} reposted</div>`:''}<div class="${orig?'quote':''}"><div class="post-head"><span class="avatar">${esc((orig||p).author[0])}</span><div><strong>${esc((orig||p).author)}</strong><small>${new Date((orig||p).created*1000).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})}</small></div></div><div class="post-text">${esc((orig||p).body)}</div>${orig?`<a class="small muted" href="#/topic/${orig.topic}" data-action="original" data-id="${orig.id}">View original post</a>`:''}</div><div class="actions"><button data-action="react" data-id="${p.id}" data-value="like" class="${my?.reaction==='like'?'selected':''}" aria-label="Like post" aria-pressed="${my?.reaction==='like'}">${icon('like')} ${reactions.filter(r=>r.reaction==='like').length}</button><button data-action="react" data-id="${p.id}" data-value="dislike" class="${my?.reaction==='dislike'?'selected':''}" aria-label="Dislike post" aria-pressed="${my?.reaction==='dislike'}">${icon('dislike')} ${reactions.filter(r=>r.reaction==='dislike').length}</button><button data-action="comments" data-id="${p.id}" aria-expanded="false">${icon('comment')} ${comments.length} Comment</button><button data-action="repost" data-id="${p.id}" class="${state.posts.some(x=>x.original===(p.original||p.id)&&x.user===state.user?.id)?'selected':''}">${icon('repost')} Repost</button><button data-action="report" data-id="${p.id}">${icon('report')} Report</button>${admin()?`<button data-action="pin" data-id="${p.id}">${p.pinned?'Unpin':'Pin'}</button><button class="danger" data-action="delete-post" data-id="${p.id}">Remove</button>`:''}</div><div class="comments" id="comments-${p.id}" hidden>${comments.map(c=>`<div class="comment"><strong>${esc(c.author)}</strong><p>${esc(c.body)}</p>${admin()?`<button class="text-button small danger" data-action="delete-comment" data-id="${c.id}">Remove comment</button>`:''}</div>`).join('')}${state.topics.find(t=>t.id===p.topic)?.status==='open'?`<form class="inline-form" data-form="comment"><input type="hidden" name="id" value="${p.id}"><input name="body" aria-label="Your comment" maxlength="2000" placeholder="Add to the conversation…" required><button class="btn" type="submit">Reply</button></form>`:''}</div></article>`}
function eventPage(id){const e=state.events.find(e=>e.id===id);if(!e||e.status==='planned'){main.innerHTML='<div class="wrap page"><h2>Details are on their way.</h2><p>We will share more once the activity is confirmed.</p><a href="#/events">Back to events</a></div>';return}main.innerHTML=`<div class="wrap page"><div class="breadcrumbs"><a href="#/events">Events</a> / ${e.status==='past'?'Event recap':'Event details'}</div><span class="badge">${esc(e.category)} · ${esc(e.status)}</span><h1 class="page-title">${esc(e.title)}</h1><p class="muted">${esc(e.date)}</p><p class="prose">${esc(e.description)}</p>${e.status!=='past'?external(e.registration,'Register for this event','btn'):''}<div class="gallery">${e.photos.map((src,i)=>`<img src="${esc(src)}" alt="${esc(e.title)} — event photograph ${i+1}" loading="lazy">`).join('')}</div>${!e.photos.length&&e.status==='past'?'<p class="muted">Photographs will be added by the society.</p>':''}</div>`}
function field(label,name,value='',type='text'){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${name==='title'?'required maxlength="160"':''}>`}
function editItem(kind,id){const item=(kind==='event'?state.events:state.topics).find(x=>x.id===id)||{};showDialog(`<h2>${id?'Edit':'New'} ${kind}</h2><form data-form="save-${kind}"><input type="hidden" name="id" value="${id||''}">${field('Title','title',item.title)}<label for="f-status">Status</label><select id="f-status" name="status">${(kind==='event'?['planned','upcoming','ongoing','past']:['upcoming','open','archived']).map(s=>`<option ${item.status===s?'selected':''} value="${s}">${s}</option>`).join('')}</select>${kind==='event'?`${field('Date or estimated period','date',item.date)}${field('Category','category',item.category)}<label for="f-description">Description / event recap</label><textarea id="f-description" name="description">${esc(item.description)}</textarea>${field('Registration link (optional)','registration',item.registration,'url')}${id?`<label for="photo-upload">Event photographs (PNG, JPEG or WebP, up to 5 MB each)</label><input id="photo-upload" type="file" accept="image/png,image/jpeg,image/webp" data-event="${id}"><small id="upload-status">${item.photos?.length||0} photographs saved</small>`:'<p class="small muted">Save the event first to add photographs.</p>'}`:`<label for="f-summary">Short introduction</label><textarea id="f-summary" name="summary">${esc(item.summary)}</textarea><label for="f-content">Official explainer / references</label><textarea id="f-content" name="content" rows="7">${esc(item.content)}</textarea><div class="form-grid"><div>${field('Explainer date','publish',item.publish,'date')}</div><div>${field('Discussion date','discussion',item.discussion,'date')}</div></div>${field('Discussion time (Malaysia time)','time',item.time)}${field('Instagram post link','instagram',item.instagram,'url')}${field('Google Meet link','meet',item.meet,'url')}`}<div class="dialog-foot"><button class="btn outline" type="button" data-action="close">Cancel</button><button class="btn" type="submit">Save ${kind}</button></div></form>`)}
async function refresh(){const y=window.scrollY;await load();render();window.scrollTo(0,y)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{if(a==='close')return dialog.close();if(a==='login')return login();if(a==='admin-login')return login('admin');if(a==='menu')return showDialog('<h2>Explore</h2><div class="two-buttons"><a class="btn outline" href="#/about" data-action="close">About us</a><a class="btn outline" href="#/events" data-action="close">Events</a><a class="btn outline" href="#/contact" data-action="close">Contact</a><a class="btn" href="#/dialogue" data-action="close">Legal knowledge</a></div>');if(a==='account')return showDialog(`<h2>${esc(state.user.name)}</h2><p>Local ${esc(state.user.role)} demo session.</p><button class="btn" data-action="logout">Sign out</button>`);if(a==='logout'){await api('logout');dialog.close();await refresh();return}if(a==='events-tab'){eventTab=b.dataset.value;const y=window.scrollY;home();window.scrollTo(0,y);return}if(a==='comments'){const c=document.getElementById('comments-'+id);c.hidden=!c.hidden;b.setAttribute('aria-expanded',String(!c.hidden));return}if(a==='original'){e.preventDefault();document.getElementById('post-'+id)?.scrollIntoView({block:'center'});return}if(a==='edit-event'||a==='edit-topic')return editItem(a.slice(5),id);if(!requireUser())return;if(a==='report')return showDialog(`<h2>Report this post</h2><p class="small muted">The society will review your report. Reporting does not automatically remove a post.</p><form data-form="report"><input name="id" type="hidden" value="${id}"><label for="reason">Reason</label><textarea id="reason" name="reason" required maxlength="1000" placeholder="Tell us what needs attention."></textarea><div class="dialog-foot"><button class="btn">Submit report</button></div></form>`);if(a.startsWith('delete-'))return showDialog(`<h2>Remove this ${a.replace('delete-','')}?</h2><p>This will remove it from the local website${a==='delete-topic'?' together with its discussion':''}.</p><form data-form="${a}"><input type="hidden" name="id" value="${id}"><div class="dialog-foot"><button type="button" class="btn outline" data-action="close">Cancel</button><button class="btn">Confirm removal</button></div></form>`);b.disabled=true;await api(a,{id,reaction:b.dataset.value});await refresh();toast(a==='repost'?'Repost updated.':'Saved.')}catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const action=f.dataset.form,data=Object.fromEntries(new FormData(f));if(['post','comment'].includes(action)&&!requireUser())return;const button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;try{if(action==='settings')data.committee=data.committee.split('\n').filter(x=>x.trim()).map(x=>x.split('|').map(y=>y.trim()));await api(action,data);if(['post','comment'].includes(action))discussionDrafts.delete(action+':'+(data.topic||data.id));if(dialog.open)dialog.close();await refresh();toast(action==='login'?'You are in the local demo.':action==='post'?'Your post is published.':action==='report'?'Report sent to the society.':'Saved.')}catch(err){const error=dialog.open?document.getElementById('form-error'):f.querySelector('.error');if(error)error.textContent=err.message;else toast(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('change',async e=>{if(e.target.id!=='photo-upload')return;const file=e.target.files[0];if(!file)return;const status=document.getElementById('upload-status');if(file.size>5000000){status.textContent='Choose an image under 5 MB.';return}status.textContent='Uploading…';try{const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});await api('upload',{id:e.target.dataset.event,image});await load();cms.decorateDialog();status.textContent='Photograph saved.';toast('Photograph saved.')}catch(err){status.textContent=err.message}});
const cms=createCMS({getState:()=>state,main,dialog,esc,api,load,render,refresh,showDialog,toast,editItem});
function restoreDiscussionDrafts(){for(const form of main.querySelectorAll('[data-form="post"],[data-form="comment"]')){const key=form.dataset.form+':'+(form.elements.topic?.value||form.elements.id?.value);if(discussionDrafts.has(key))form.elements.body.value=discussionDrafts.get(key)}}
document.addEventListener('input',e=>{const form=e.target.closest('[data-form="post"],[data-form="comment"]');if(form&&e.target.name==='body')discussionDrafts.set(form.dataset.form+':'+(form.elements.topic?.value||form.elements.id?.value),e.target.value)});
window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render()});
try{await load();render()}catch(err){main.innerHTML=`<div class="wrap page"><h2>Unable to load.</h2><p>${esc(err.message)}</p><button class="btn" onclick="location.reload()">Try again</button></div>`}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'list_legal_topics',description:'Read the legal discussion topics visible on this local website.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{await load();return state.topics.map(({id,title,status})=>({id,title,status}))}})}catch{}}
